import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const mount=document.querySelector('#game');
const scene=new THREE.Scene();scene.background=new THREE.Color(0x9cae83);scene.fog=new THREE.FogExp2(0x9cae83,.012);
const camera=new THREE.OrthographicCamera(-18,18,12,-12,.1,180);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;mount.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xe6edce,0x59644b,2.1));const sun=new THREE.DirectionalLight(0xffe6b5,2.7);sun.position.set(-25,40,18);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38;sun.shadow.bias=-.0003;scene.add(sun);
const mat=(color,rough=.9,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={grass:[0x738a55,0x7d915c,0x71834d,0x829362],dark:mat(0x536e45),path:mat(0xb7a078),path2:mat(0xc2ad80),wood:mat(0x75513a),bark:mat(0x58402f),leaf:[mat(0x536f45),mat(0x627d4d),mat(0x718851),mat(0x455f40)],rock:[mat(0x777b6b),mat(0x898778),mat(0x626e64)],gold:mat(0xd0a356),water:mat(0x79968b,.4),white:mat(0xe0d5bb),red:mat(0x9c4840),cloth:mat(0x3e6570),steel:mat(0x9ba69b,.4,.35)};
function mesh(geo,material,parent=scene){const m=new THREE.Mesh(geo,material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function box(parent,x,y,z,sx,sy,sz,material){const m=mesh(new THREE.BoxGeometry(sx,sy,sz),material,parent);m.position.set(x,y,z);return m}
function sphere(parent,x,y,z,r,material,scale=[1,1,1]){const m=mesh(new THREE.SphereGeometry(r,14,10),material,parent);m.position.set(x,y,z);m.scale.set(...scale);return m}
const ground=mesh(new THREE.PlaneGeometry(120,120),mat(0x778858));ground.rotation.x=-Math.PI/2;ground.position.y=-.12;ground.receiveShadow=true;
// softly mottled grass patches and a winding pale road
let seed=6412;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
for(let i=0;i<650;i++){let x=(rand()-.5)*100,z=(rand()-.5)*90;let g=mesh(new THREE.CircleGeometry(.15+rand()*.65,7),mats.grass[Math.floor(rand()*mats.grass.length)]);g.rotation.x=-Math.PI/2;g.rotation.z=rand()*6.28;g.position.set(x,-.105,z);g.scale.y=.5;g.castShadow=false;g.receiveShadow=false}
// road from village through the meadow
const roadPts=[new THREE.Vector3(-18,-.07,8),new THREE.Vector3(-10,-.065,6),new THREE.Vector3(-3,-.06,5),new THREE.Vector3(4,-.055,3),new THREE.Vector3(11,-.05,-1),new THREE.Vector3(18,-.045,-7),new THREE.Vector3(24,-.04,-12)];const roadCurve=new THREE.CatmullRomCurve3(roadPts);const road=mesh(new THREE.TubeGeometry(roadCurve,90,2.5,8,false),mats.path);road.castShadow=false;road.receiveShadow=true;
for(let i=0;i<85;i++){const t=rand();const p=roadCurve.getPoint(t);const side=rand()<.5?-1:1;const g=mesh(new THREE.CircleGeometry(.12+rand()*.2,6),rand()<.5?mats.path2:mats.path);g.rotation.x=-Math.PI/2;g.position.set(p.x+(rand()*4-2),-.038,p.z+side*(rand()*2.2));g.castShadow=false}
// creek in the northern wood
const creek=mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3([new THREE.Vector3(-20,-.08,-16),new THREE.Vector3(-12,-.07,-20),new THREE.Vector3(-2,-.07,-18),new THREE.Vector3(8,-.07,-23),new THREE.Vector3(18,-.07,-19)]),60,1.25,8,false),mats.water);creek.castShadow=false;
const obstacles=[];const nodes=[];const slimes=[];const decor=[];
function makeTree(x,z,size=1){const group=new THREE.Group();scene.add(group);group.position.set(x,0,z);const trunk=mesh(new THREE.CylinderGeometry(.18*size,.29*size,1.7*size,8),mats.bark,group);trunk.position.y=.78*size;trunk.rotation.z=(rand()-.5)*.12;for(let i=0;i<3;i++){const crown=mesh(new THREE.IcosahedronGeometry((1.05-i*.13)*size,1),mats.leaf[Math.floor(rand()*mats.leaf.length)],group);crown.position.set((rand()-.5)*.34*size,(1.7+i*.65)*size,(rand()-.5)*.3*size);crown.scale.set(1,.83,1);crown.rotation.y=rand()*6}obstacles.push({x,z,r:.65*size});decor.push(group);return group}
function makeRock(x,z,size=1,material){const r=mesh(new THREE.DodecahedronGeometry(size,0),material||mats.rock[Math.floor(rand()*mats.rock.length)]);r.position.set(x,size*.45,z);r.scale.set(1,.7,.85);r.rotation.set(rand()*.2,rand()*3,rand()*.2);obstacles.push({x,z,r:size*.85});return r}
// forest edge and scattered trees
for(let i=0;i<115;i++){let x,z;if(i<55){x=(rand()-.5)*94;z=-29-rand()*14}else{x=(rand()<.5?-1:1)*(27+rand()*19);z=(rand()-.5)*68}if(Math.abs(x)<13&&z>-13&&z<14)continue;if(Math.abs(x)<23&&z>-26&&z<-14)continue;makeTree(x,z,.75+rand()*.65)}
// clearings: stone circles, flowers and fallen logs
for(let i=0;i<240;i++){let x=(rand()-.5)*60,z=(rand()-.5)*55;if(Math.abs(x)<14&&Math.abs(z)<12)continue;const flower=mesh(new THREE.SphereGeometry(.055,6,5),[mat(0xe5d29a),mat(0xd79c7c),mat(0xc3bb77),mat(0xe8e4cf)][Math.floor(rand()*4)]);flower.position.set(x,.12,z);flower.castShadow=false}
for(let i=0;i<18;i++)makeRock((rand()-.5)*54,(rand()-.5)*50,.35+rand()*.55);
// player, in heroic forest-green adventurer kit
const player=new THREE.Group();scene.add(player);player.position.set(-2,0,1);const avatar=new THREE.Group();player.add(avatar);
sphere(avatar,0,1.25,0,.42,mats.cloth,[.8,1.1,.65]);sphere(avatar,0,2.02,0,.32,mat(0xd0a878),[.9,1, .9]);
// hood/cap and face details
const hood=mesh(new THREE.ConeGeometry(.39,.48,8),mat(0x344c3e),avatar);hood.position.y=2.27;hood.rotation.y=.35; sphere(avatar,0,1.94,.04,.27,mat(0xc89e6d),[.9,.85,.85]);
const eyeMat=mat(0x28251e);sphere(avatar,-.105,2,.25,.035,eyeMat);sphere(avatar,.105,2,.25,.035,eyeMat);
const cape=mesh(new THREE.ConeGeometry(.45,.95,6),mat(0x9b443a),avatar);cape.position.set(0,1.17,-.27);cape.rotation.x=-.25;
const belt=mesh(new THREE.TorusGeometry(.3,.055,6,12),mats.gold,avatar);belt.rotation.x=Math.PI/2;belt.position.y=1.15;
const armL=box(avatar,-.39,1.4,0,.2,.65,.22,mats.cloth);armL.rotation.z=-.16;const armR=box(avatar,.39,1.4,0,.2,.65,.22,mats.cloth);armR.rotation.z=.16;
const legL=box(avatar,-.17,.48,0,.24,.62,.27,mats.bark);const legR=box(avatar,.17,.48,0,.24,.62,.27,mats.bark);
const sword=new THREE.Group();avatar.add(sword);const blade=box(sword,.55,1.43,.04,.12,.95,.08,mats.steel);blade.rotation.z=-.2;const guard=box(sword,.52,1.02,.04,.42,.09,.13,mats.gold);guard.rotation.z=-.2;const grip=box(sword,.48,.86,.04,.1,.28,.1,mats.bark);grip.rotation.z=-.2;sword.rotation.z=.22;
const shadow=mesh(new THREE.CircleGeometry(.5,20),new THREE.MeshBasicMaterial({color:0x182319,transparent:true,opacity:.35,depthWrite:false}),player);shadow.rotation.x=-Math.PI/2;shadow.position.y=.015;shadow.castShadow=false;
// gatherable resource props
a function_dummy;

