// gatherable resources and friendly wayfarers
function makeNode(type,x,z){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);let icon='';if(type==='wood'){const stump=mesh(new THREE.CylinderGeometry(.42,.52,.5,9),mats.wood,g);stump.position.y=.2;const cut=mesh(new THREE.CylinderGeometry(.3,.3,.035,9),mat(0xc19665),g);cut.position.y=.46;icon='🪵'}else if(type==='ore'){makeRock(0,0,.01);const rock=mesh(new THREE.DodecahedronGeometry(.56,0),mats.rock[0],g);rock.position.y=.39;rock.scale.set(1,.8,.9);for(let i=0;i<3;i++){const c=mesh(new THREE.OctahedronGeometry(.19),mat(0x91a6a0,.45,.45),g);c.position.set((i-1)*.25,.58+(i%2)*.2,.1);icon='⛏️'}}else{const bush=mesh(new THREE.IcosahedronGeometry(.52,1),mat(0x486944),g);bush.position.y=.44;bush.scale.set(1,.75,1);for(let i=0;i<5;i++){const berry=sphere(g,(rand()-.5)*.6,.55+rand()*.35,(rand()-.5)*.6,.08,mat(0xb7564e));berry.castShadow=false}icon='🍓'}nodes.push({type,x,z,group:g,icon,ready:true,respawn:0});return g}
makeNode('wood',-8,5);makeNode('wood',-12,-4);makeNode('wood',8,9);makeNode('ore',12,4);makeNode('ore',-10,13);makeNode('ore',18,-3);makeNode('berry',3,-10);makeNode('berry',-14,4);makeNode('berry',9,-13);
// friendly outpost and elder
function makeNPC(x,z){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);sphere(g,0,1.15,0,.38,mat(0x7d6956),[.9,1.1,.7]);sphere(g,0,1.9,0,.31,mat(0xd0a477));const hat=mesh(new THREE.ConeGeometry(.46,.43,7),mat(0x9a7849),g);hat.position.y=2.2;hat.rotation.z=.2;const robe=mesh(new THREE.ConeGeometry(.59,1.25,8),mat(0x625747),g);robe.position.y=.65;const staff=mesh(new THREE.CylinderGeometry(.04,.055,2.1,7),mats.wood,g);staff.position.set(.56,1,0);const orb=sphere(g,.56,2.07,0,.17,mat(0xd5c077,.25,.25));orb.material.emissive=new THREE.Color(0x645021);obstacles.push({x,z,r:.55});return g}
makeNPC(-15,8);
// slimes
const slimeMat=mat(0x78b973,.38),slimeBelly=mat(0xb9d790,.6),slimeEye=mat(0x263a32,.45);
function spawnSlime(x,z,level=1){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);const body=sphere(g,0,.49,0,.56,slimeMat,[1,.83,1]);sphere(g,0,.35,.27,.32,slimeBelly,[1,.48,.55]);sphere(g,-.17,.65,.45,.055,slimeEye);sphere(g,.17,.65,.45,.055,slimeEye);const shine=sphere(g,-.21,.73,.47,.045,mat(0xf1edcf));shine.castShadow=false;const hpbg=mesh(new THREE.PlaneGeometry(.9,.08),new THREE.MeshBasicMaterial({color:0x1d2921,transparent:true,opacity:.8}),g);hpbg.position.y=1.35;const hpf=mesh(new THREE.PlaneGeometry(.86,.045),new THREE.MeshBasicMaterial({color:0xcf6653}),g);hpf.position.set(0,1.36,.008);slimes.push({group:g,x,z,hp:3,maxHp:3,level,alive:true,speed:1.05+rand()*.35,phase:rand()*8,body,hpf,hpbg,attackAt:0});return g}
spawnSlime(8,-5);spawnSlime(14,-10);spawnSlime(-5,-15);spawnSlime(20,7);spawnSlime(-18,-9);
// small timbered hamlet around the starting clearing
function makeHouse(x,z,scale=1){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);box(g,0,.9,0,3*scale,1.8*scale,2.6*scale,mat(0x8e6e4b));const roof=mesh(new THREE.ConeGeometry(2.35*scale,1.55*scale,4),mat(0x653f33),g);roof.position.y=2.35*scale;roof.rotation.y=Math.PI/4;roof.scale.z=.78;box(g,0,.75,1.32*scale,.65*scale,1.4*scale,.08,mat(0x42342a));const window1=box(g,-.92*scale,1.18*scale,1.34*scale,.4*scale,.42*scale,.06,mat(0xe4bd70));window1.material.emissive=new THREE.Color(0x503414);obstacles.push({x,z,r:1.8*scale});}
makeHouse(-20,13,1.05);makeHouse(-24,17,.75);makeHouse(-16,18,.8);

