const state={hp:100,maxHp:100,xp:0,level:1,gold:12,potions:2,slimes:0,wood:0,ore:0,berries:0,meat:0,dead:false,attackCd:0,rollCd:0,gatherCd:0,attackHeld:false,rollTime:0,attackTime:0,move:new THREE.Vector3(),moving:false,dir:new THREE.Vector3(0,0,1)};
