function inventoryModal(){ui.modalTitle.textContent='Wayfarer’s pack';ui.modalBody.innerHTML=`<div style="display:flex;justify-content:space-between;color:#e3c47e"><span>Level ${state.level} adventurer</span><span>◈ ${state.gold} silver</span></div><div class="inventory-grid"><div class="inv-item">🧪<b>${state.potions}</b><small>Healing tonic</small></div><div class="inv-item">🪵<b>${state.wood}</b><small>Wildwood</small></div><div class="inv-item">⛏️<b>${state.ore}</b><small>Iron ore</small></div><div class="inv-item">🍓<b>${state.berries}</b><small>Wild berries</small></div><div class="inv-item">🫧<b>${state.slimes}</b><small>Slimes slain</small></div><div class="inv-item">🥩<b>${state.meat}</b><small>Slime gel</small></div></div><p style="margin-bottom:0;color:#aab8a7">Gather resources around the meadow. Defeating slimes earns experience and silver.</p>`;ui.modal.classList.add('show')}
function mapModal(){ui.modalTitle.textContent='Greenhollow & the wild meadow';ui.modalBody.innerHTML=`<p>The old road winds east from Greenhollow. Slimes roam the northern meadow; look for stumps, ore and berry bushes along the trail.</p><div style="height:180px;border:1px solid #d5bd7644;border-radius:10px;background:linear-gradient(135deg,#40583c,#809265);position:relative;overflow:hidden"><div style="position:absolute;left:8%;top:62%;width:86%;height:4px;background:#c4aa7b;transform:rotate(-18deg);border-radius:8px"></div><span style="position:absolute;left:17%;top:65%">🏠</span><span style="position:absolute;left:48%;top:42%">🫧</span><span style="position:absolute;left:69%;top:28%">🫧</span><span style="position:absolute;left:56%;top:75%">🪵</span><span style="position:absolute;left:83%;top:58%">⛏️</span><span style="position:absolute;left:47%;top:58%;font-size:21px">🛡️</span><div style="position:absolute;bottom:8px;left:10px;font-size:9px;letter-spacing:1px">GREENHOLLOW MEADOW</div></div>`;ui.modal.classList.add('show')}
document.querySelector('#inventoryBtn').addEventListener('click',inventoryModal);document.querySelector('#mapBtn').addEventListener('click',mapModal);document.querySelector('#modalClose').addEventListener('click',()=>ui.modal.classList.remove('show'));ui.modal.addEventListener('click',e=>{if(e.target===ui.modal)ui.modal.classList.remove('show')});
// hotbar and touch actions share the same abilities
function doAction(a){if(a==='attack')attack();if(a==='roll')roll();if(a==='potion')usePotion();if(a==='gather')gather()}
document.querySelectorAll('[data-action]').forEach(el=>{el.addEventListener('click',e=>{e.stopPropagation();doAction(el.dataset.action)});if(el.dataset.action==='attack'){el.addEventListener('pointerdown',()=>state.attackHeld=true);el.addEventListener('pointerup',()=>state.attackHeld=false);el.addEventListener('pointercancel',()=>state.attackHeld=false);el.addEventListener('pointerleave',()=>state.attackHeld=false)}});
const keys={};window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.repeat)return;if(e.code==='Space')attack();if(e.code==='KeyE')interact();if(e.code==='Digit1')attack();if(e.code==='Digit2')roll();if(e.code==='Digit3')usePotion();if(e.code==='Digit4')gather();if(e.code==='KeyI')inventoryModal();if(e.code==='Escape')ui.modal.classList.remove('show')});window.addEventListener('keyup',e=>{keys[e.code]=false});
let touchVec={x:0,y:0};const stick=document.querySelector('#stick'),knob=document.querySelector('#knob');let stickId=null;function stickMove(e){const rect=stick.getBoundingClientRect(),cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,dx=e.clientX-cx,dy=e.clientY-cy,lim=rect.width*.36,d=Math.hypot(dx,dy),k=d>lim?lim/d:1;touchVec={x:dx*k/lim,y:dy*k/lim};knob.style.left=`${50+touchVec.x*36}%`;knob.style.top=`${50+touchVec.y*36}%`}
stick.addEventListener('pointerdown',e=>{e.preventDefault();stickId=e.pointerId;stick.setPointerCapture(stickId);stickMove(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stickMove(e)});function resetStick(){stickId=null;touchVec={x:0,y:0};knob.style.left='50%';knob.style.top='50%'}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
// click/tap the world to set a move destination
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0);renderer.domElement.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'||e.button!==0)return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);const hit=new THREE.Vector3();if(raycaster.ray.intersectPlane(groundPlane,hit)){state.move.copy(hit);state.moving=true}});

