+function die(){if(state.dead)return;state.dead=true;state.hp=0;refresh();ui.modalTitle.textContent='The meadow claims you';ui.modalBody.innerHTML=`<p>You fall beneath the slimes’ relentless assault. Your belongings are safe in Greenhollow.</p><div class="action-row"><button id="respawn">Rise again</button></div>`;ui.modal.classList.add('show');document.querySelector('#respawn').onclick=()=>{player.position.set(-2,0,1);state.hp=state.maxHp;state.dead=false;ui.modal.classList.remove('show');refresh();toast('You awaken at Greenhollow.')}}
+function resize(){const aspect=innerWidth/innerHeight;const height=24;camera.left=-height*aspect/2;camera.right=height*aspect/2;camera.top=height/2;camera.bottom=-height/2;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8))}window.addEventListener('resize',resize);resize();drawMap();refresh();setTimeout(()=>document.querySelector('#loading').classList.add('hide'),750);toast('Welcome to Greenhollow, Wayfarer.');sayNotice('WASD to move · Space to strike · E to interact');requestAnimationFrame(update);

